import { useEffect } from 'react';
import { useLocation, useSearchParams } from 'react-router-dom';
import { Headphones } from 'lucide-react';
import MobileLayout from '../../components/MobileLayout';
import { PODCAST_CHANNELS } from './catalog';
import PodcastChannelRow from './PodcastChannelRow';
import PodcastPlayer from './PodcastPlayer';

export default function PodcastPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const { hash } = useLocation();
  useEffect(() => {
    const channelId = hash.slice(1);
    if (!PODCAST_CHANNELS.some((item) => item.id === channelId)) return;
    const frame = window.requestAnimationFrame(() =>
      document.getElementById(channelId)?.scrollIntoView({ block: 'start' }),
    );
    return () => window.cancelAnimationFrame(frame);
  }, [hash]);
  const videoId = searchParams.get('v');
  const channel = PODCAST_CHANNELS.find((item) =>
    item.videos.some((video) => video.id === videoId),
  );
  const video = channel?.videos.find((item) => item.id === videoId);
  const closePlayer = () => {
    const next = new URLSearchParams(searchParams);
    next.delete('v');
    setSearchParams(next, { replace: true });
  };
  const videoCount = PODCAST_CHANNELS.reduce(
    (count, item) => count + item.videos.length,
    0,
  );

  return (
    <MobileLayout>
      <main className="pb-3 pt-[max(20px,env(safe-area-inset-top))]">
        <header className="px-4 pb-6">
          <div className="mb-4 flex items-center gap-3">
            <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10 text-primary dark:bg-indigo-500/15 dark:text-indigo-300">
              <Headphones size={25} />
            </span>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-gray-900 dark:text-white">
                Podcast
              </h1>
              <p className="mt-0.5 text-xs font-medium text-gray-500 dark:text-neutral-400">
                {PODCAST_CHANNELS.length} kênh · {videoCount} video
              </p>
            </div>
          </div>
          <p className="text-sm leading-6 text-gray-500 dark:text-neutral-400">
            Nghe tiếng Anh mỗi ngày cùng những kênh YouTube yêu thích. Vuốt để
            khám phá 20 video của mỗi kênh.
          </p>
        </header>
        <nav
          aria-label="Chọn kênh Podcast"
          className="mb-7 flex gap-2 overflow-x-auto px-4 pb-2"
        >
          {PODCAST_CHANNELS.map((item) => (
            <a
              key={item.id}
              href={`#${item.id}`}
              className="shrink-0 rounded-full border border-gray-200 bg-white px-3 py-2 text-xs font-semibold text-gray-600 hover:border-primary hover:text-primary dark:border-neutral-700 dark:bg-neutral-900 dark:text-neutral-300"
            >
              {item.name}
            </a>
          ))}
        </nav>
        {videoId && !video && (
          <p
            role="status"
            className="mx-4 mb-5 rounded-xl bg-amber-50 p-3 text-sm text-amber-800 dark:bg-amber-950/40 dark:text-amber-200"
          >
            Video này không có trong danh sách. Hãy chọn một video bên dưới.
          </p>
        )}
        <div className="space-y-7">
          {PODCAST_CHANNELS.map((item) => (
            <PodcastChannelRow key={item.id} channel={item} />
          ))}
        </div>
      </main>
      {video && channel && (
        <PodcastPlayer video={video} channel={channel} onClose={closePlayer} />
      )}
    </MobileLayout>
  );
}
